/* ============================================================================
 * Latest-decision highlight on the home page (index.html).
 * Polls /api/v1/decisions/recent and fills the #latest-decision card.
 *   - Shows the most recent decision with action + ticker + short reason.
 *   - Hidden (display:none via [hidden]) when there are no decisions.
 *   - Clicking the row navigates to decision-detail.html?id=… via the link
 *     generated by window.FA.detailUrl().
 * ============================================================================ */
(function () {
  'use strict';

  var $slot = document.getElementById('latest-decision');
  var $body = $slot ? $slot.querySelector('.latest-body') : null;
  if (!$slot || !$body) return; // Page doesn't have the slot — nothing to do.

  function render(d) {
    if (!d) {
      $slot.hidden = true;
      return;
    }
    $slot.hidden = false;
    $slot.classList.remove('empty');

    var action = (d.action || 'HOLD').toString().toUpperCase();
    var conf = (d.confidence !== undefined && d.confidence !== null)
      ? Math.round(Number(d.confidence) * 100) + '%'
      : '—';
    var ts = d.effective_at || d.created_at || null;
    var when = ts ? window.FA.fmtTime(new Date(ts)) : '—';
    var reason = (d.supervisor_reasoning || d.reason || '').toString();
    if (reason.length > 100) reason = reason.slice(0, 98) + '…';

    $body.innerHTML = ''
      + '<a class="latest-symbol" href="' + window.FA.esc(window.FA.detailUrl(d.decision_id)) + '">'
      +   window.FA.esc(d.ticker || '—')
      + '</a>'
      + '<span class="badge action-' + window.FA.esc(action.toLowerCase()) + '">'
      +   window.FA.esc(action)
      + '</span>'
      + '<span class="latest-meta">güven / conf: ' + window.FA.esc(conf) + '</span>'
      + '<span class="latest-meta">' + window.FA.esc(when) + '</span>'
      + '<span class="latest-reason" title="' + window.FA.esc(reason) + '">'
      +   (reason ? window.FA.esc(reason) : '—')
      + '</span>';
  }

  function tick() {
    window.FA.fetchJson(window.FA.API_BASE + '/v1/decisions/recent', { params: { limit: 1 } })
      .then(function (data) {
        var list = window.FA.normalizeList(data);
        render(list && list.length ? list[0] : null);
      })
      .catch(function () { render(null); });
  }

  // Wait until app.js (window.FA) has booted before polling.
  function boot() {
    if (!window.FA) {
      // app.js hasn't run yet — wait one tick.
      return setTimeout(boot, 30);
    }
    tick();
    window.FA.attachRefreshLoop(tick, 30000);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();